package com.edunest.backend.modules.syllabus.controller; import com.edunest.backend.common.util.PublicIdUtils; import com.edunest.backend.modules.syllabus.dto.SyllabusResponse; import com.edunest.backend.modules.syllabus.service.SyllabusService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/syllabus") @RequiredArgsConstructor public class SyllabusController { private final SyllabusService s; @GetMapping("/subject/{subjectId}") public SyllabusResponse get(@PathVariable String subjectId){return s.getSubjectSyllabus(PublicIdUtils.parseSubjectId(subjectId));} }